+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import com.vaadin.flow.component.grid.Grid;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-001", "BR-003"})
+    void gridListsAllVetsWithSpecialties() {
+        // No authentication is performed, covering BR-003 (Anonymous Access).
+        assertDoesNotThrow(() -> navigate(VetsView.class), "Expected /vets to resolve to VetsView");
+
+        Grid<Vet> grid = vetsGrid();
+        assertEquals(6, test(grid).size());
+        assertEquals("James", test(grid).getCellText(0, 0));
+        assertEquals("Carter", test(grid).getCellText(0, 1));
+        assertEquals("none", test(grid).getCellText(0, 2));
+        assertEquals("radiology", test(grid).getCellText(3, 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreOrderedAlphabetically() {
+        navigate(VetsView.class);
+
+        // Linda Douglas holds surgery (id 2) and dentistry (id 3).
+        assertEquals("dentistry, surgery", test(vetsGrid()).getCellText(1, 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void noVetsRendersEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetsView.class);
+
+        assertEquals(0, test(vetsGrid()).size(), "Expected the vets grid to have no rows");
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> vetsGrid() {
+        return find(Grid.class).single();
+    }
+}
